/**
 * M0.5B — offline live trust setup.
 *
 * Run this with the network DOWN. It refuses to run otherwise.
 *
 * Why it is a standalone script: the assistant driving this project runs
 * remotely, so it cannot be interactive while the machine is offline. The root
 * key must therefore be generated by a local script with no operator in the
 * loop, and only public material is handed back afterwards.
 *
 * What it does, in one offline run:
 *   1. asserts the machine has no network route
 *   2. generates the provisional live root, and every live signing key
 *   3. stores each private key DPAPI-protected — plaintext never touches disk
 *   4. seals a `purpose: live` registry with the root
 *   5. writes the public registry plus a root fingerprint file
 *
 * It never contacts the network, never writes a plaintext private key, and
 * never touches the development key set or the development registry.
 *
 * Usage (PowerShell, network off):
 *   $env:EXOSUIT_LIVE_KEY_DIR = "$env:USERPROFILE\.exosuit-live-keys"
 *   node scripts/completion/offline-live-trust-setup.mjs
 */

import { execFileSync } from "node:child_process";
import { createHash, generateKeyPairSync, sign } from "node:crypto";
import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { lookup } from "node:dns/promises";
import { hostname } from "node:os";
import { join, resolve } from "node:path";

const REPO_ROOT = resolve(process.cwd());
const OUT_DIR = join(REPO_ROOT, "docs", "qa", "completion-m05");
const KEY_DIR = resolve(
  process.env.EXOSUIT_LIVE_KEY_DIR ?? join(process.env.USERPROFILE ?? ".", ".exosuit-live-keys"),
);

const TRUST_POSTURE = {
  trustPosture: "provisional_personal_mvp",
  rootGeneratedOnAttestedHost: true,
  productionEligible: false,
};

const LIVE_KEYS = {
  "live-manifest-1": ["manifest"],
  "live-ledger-1": ["ledger"],
  "live-evidence-1": ["evidence"],
  "live-host-1": ["host"],
  "live-technical-review-1": ["technical_review"],
  "live-owner-1": ["owner_acceptance"],
  "live-release-1": ["release_approval"],
};

/* --------------------------------------------------------- preconditions */

async function assertOffline() {
  const failures = [];

  try {
    await lookup("github.com");
    failures.push("DNS resolved github.com");
  } catch {
    // expected when offline
  }

  try {
    const ping = execFileSync("ping", ["-n", "1", "-w", "1500", "1.1.1.1"], { encoding: "utf8" });
    if (/TTL=/i.test(ping)) failures.push("1.1.1.1 replied to ping");
  } catch {
    // expected when offline
  }

  try {
    const profiles = execFileSync(
      "powershell",
      ["-NoProfile", "-NonInteractive", "-Command",
        "@(Get-NetConnectionProfile | Where-Object { $_.IPv4Connectivity -eq 'Internet' -or $_.IPv6Connectivity -eq 'Internet' }).Count"],
      { encoding: "utf8" },
    ).trim();
    if (profiles !== "0") failures.push(`${profiles} network profile(s) still report Internet connectivity`);
  } catch {
    // if the query fails we fall back to the checks above
  }

  if (failures.length > 0) {
    console.error("REFUSING TO GENERATE THE LIVE ROOT — the machine is still online:\n");
    for (const failure of failures) console.error(`  - ${failure}`);
    console.error("\nDisable the network adapter and run this again:");
    console.error("  Disable-NetAdapter -Name 'Wi-Fi' -Confirm:$false   (elevated)");
    process.exit(1);
  }
  console.log("Offline precondition satisfied: no DNS, no ping reply, no Internet profile.");
}

/* --------------------------------------------------------------- helpers */

function psQuote(value) {
  return `'${String(value).replace(/'/g, "''")}'`;
}

/**
 * DPAPI-protects a PEM passed over stdin, so the plaintext never reaches disk
 * and never appears on a command line.
 */
function protectToVault(pem, vaultPath) {
  execFileSync(
    "powershell",
    ["-NoProfile", "-NonInteractive", "-Command",
      "Add-Type -AssemblyName System.Security; "
      + "$b=[Convert]::FromBase64String([Console]::In.ReadToEnd().Trim()); "
      + "$p=[Security.Cryptography.ProtectedData]::Protect($b,$null,'CurrentUser'); "
      + `[IO.File]::WriteAllBytes(${psQuote(vaultPath)},$p)`],
    { input: Buffer.from(pem, "utf8").toString("base64"), encoding: "utf8" },
  );

  const roundTrip = execFileSync(
    "powershell",
    ["-NoProfile", "-NonInteractive", "-Command",
      "Add-Type -AssemblyName System.Security; "
      + `$b=[IO.File]::ReadAllBytes(${psQuote(vaultPath)}); `
      + "$u=[Security.Cryptography.ProtectedData]::Unprotect($b,$null,'CurrentUser'); "
      + "[Console]::Out.Write([Convert]::ToBase64String($u))"],
    { encoding: "utf8", maxBuffer: 32 * 1024 * 1024 },
  );
  if (Buffer.from(roundTrip.trim(), "base64").toString("utf8").trim() !== pem.trim()) {
    throw new Error(`DPAPI vault for ${vaultPath} did not round-trip.`);
  }
}

function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  if (value !== null && typeof value === "object") {
    const entries = Object.entries(value)
      .filter(([, item]) => item !== undefined)
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([key, item]) => `${JSON.stringify(key)}:${canonicalJson(item)}`);
    return `{${entries.join(",")}}`;
  }
  return JSON.stringify(value);
}

function machineIdentity() {
  return `machine-${createHash("sha256").update(hostname()).digest("hex").slice(0, 16)}`;
}

/* ------------------------------------------------------------------ main */

await assertOffline();

if (KEY_DIR.startsWith(REPO_ROOT)) {
  console.error(`Live key directory must be outside the repository: ${KEY_DIR}`);
  process.exit(1);
}
mkdirSync(KEY_DIR, { recursive: true });
mkdirSync(OUT_DIR, { recursive: true });

for (const keyId of ["live-root-1", ...Object.keys(LIVE_KEYS)]) {
  if (existsSync(join(KEY_DIR, `${keyId}.pem.dpapi`))) {
    console.error(`${keyId} already exists in ${KEY_DIR}. Refusing to overwrite live key material.`);
    process.exit(1);
  }
}

// ---- provisional live root ----
const root = generateKeyPairSync("ed25519");
const rootPublicKey = root.publicKey.export({ format: "der", type: "spki" }).toString("base64");
const rootPem = root.privateKey.export({ format: "pem", type: "pkcs8" }).toString();
protectToVault(rootPem, join(KEY_DIR, "live-root-1.pem.dpapi"));
const rootFingerprint = createHash("sha256").update(Buffer.from(rootPublicKey, "base64")).digest("hex");
console.log(`Provisional live root generated. Fingerprint:\n  ${rootFingerprint}`);

// ---- live signing keys ----
const now = new Date();
const notAfter = new Date(now.getTime() + 365 * 86_400_000);
const machineId = machineIdentity();

const keys = Object.entries(LIVE_KEYS).map(([keyId, roles]) => {
  const pair = generateKeyPairSync("ed25519");
  protectToVault(
    pair.privateKey.export({ format: "pem", type: "pkcs8" }).toString(),
    join(KEY_DIR, `${keyId}.pem.dpapi`),
  );
  return {
    keyId,
    algorithm: "ed25519",
    publicKey: pair.publicKey.export({ format: "der", type: "spki" }).toString("base64"),
    roles: [...roles],
    ...(roles.includes("host") ? { machineId } : {}),
    notBefore: now.toISOString(),
    notAfter: notAfter.toISOString(),
  };
});

// ---- seal the live registry with the root ----
const core = {
  contractVersion: 2,
  registryId: `live-${now.toISOString().slice(0, 10)}-${hostname().toLowerCase()}`,
  purpose: "live",
  version: 1,
  previousRegistryHash: "0".repeat(64),
  issuedAt: now.toISOString(),
  expiresAt: notAfter.toISOString(),
  keys,
  revocations: [],
  rootKeyId: "live-root-1",
  rootPublicKey,
};
const registry = {
  ...core,
  signature: sign(null, Buffer.from(canonicalJson(core), "utf8"), root.privateKey).toString("base64url"),
};

writeFileSync(join(OUT_DIR, "keys.json"), `${JSON.stringify(registry, null, 2)}\n`, "utf8");
writeFileSync(
  join(OUT_DIR, "root-fingerprint.json"),
  `${JSON.stringify({
    rootKeyId: "live-root-1",
    rootPublicKey,
    fingerprint: rootFingerprint,
    machineId,
    hostname: hostname(),
    generatedAt: now.toISOString(),
    generatedOffline: true,
    ...TRUST_POSTURE,
  }, null, 2)}\n`,
  "utf8",
);

console.log(`\nSealed live registry: ${join(OUT_DIR, "keys.json")}`);
console.log(`Wrote fingerprint:    ${join(OUT_DIR, "root-fingerprint.json")}`);
console.log(`Private keys (DPAPI): ${KEY_DIR}`);
console.log(`\nTrust posture: ${TRUST_POSTURE.trustPosture}, productionEligible=${TRUST_POSTURE.productionEligible}`);
console.log("\nNo plaintext private key was written to disk. You may reconnect the network now.");
